17	// RecordID 是一次成功保存产生的、在同一存档目录内唯一的记录标识。
18	type RecordID string
19	
20	// archiveFormatVersion 是存档目录布局版本，写入目录标记中。
21	const archiveFormatVersion = 1
22	
23	// recordFormatVersion 是当前唯一支持的记录格式版本。记录格式与存档目录
24	// 布局版本是两个独立的编号：目录可打开不代表其中每条记录都能被理解，
25	// 格式编号不是该值的记录（缺失、零、负值或其他正整数）一律按损坏处理，
26	// 即使其校验和匹配、世界状态合法。
27	const recordFormatVersion = 1
