29	// envelope 是记录文件在磁盘上的完整编码。
30	type envelope struct {
31		// Format 是记录格式版本。
32		Format int `json:"format"`
33		// ID 是本条记录的唯一标识。
34		ID RecordID `json:"id"`
35		// Parent 是父记录标识；直接建立的槽首条记录为空。
36		Parent RecordID `json:"parent,omitempty"`
37		// SlotFirst 标记本条记录是否为其所在槽的首条记录
38		// （直接建立的根记录，或从其他槽分出的分支记录）。
39		SlotFirst bool `json:"slotFirst"`
40		// Checksum 是对（格式版本、ID、父记录、首记录标记、完整世界状态）
41		// 计算出的内容校验和，因此父记录关系也被纳入校验。
42		Checksum string `json:"checksum"`
43		// State 是完整世界数据：种子、规则与全部状态。
44		State State `json:"state"`
45	}
46	
47	// checksumPayload 是参与校验和计算的规范内容。
48	type checksumPayload struct {
49		Format    int      `json:"format"`
50		ID        RecordID `json:"id"`
51		Parent    RecordID `json:"parent"`
52		SlotFirst bool     `json:"slotFirst"`
53		State     State    `json:"state"`
54	}
