56	func computeChecksum(e *envelope) string {
57		p := checksumPayload{
58			Format:    e.Format,
59			ID:        e.ID,
60			Parent:    e.Parent,
61			SlotFirst: e.SlotFirst,
62			State:     e.State,
63		}
64		// encoding/json 对 map 按键排序输出，同一状态总是得到相同字节。
65		b, _ := json.Marshal(p)
66		sum := sha256.Sum256(b)
67		return hex.EncodeToString(sum[:])
68	}
