70	// newRecordID 产生目录内唯一的记录标识。
71	func newRecordID() (RecordID, error) {
72		var b [16]byte
73		if _, err := rand.Read(b[:]); err != nil {
74			return "", err
75		}
76		return RecordID("r" + hex.EncodeToString(b[:])), nil
77	}
