83	// writeRecord 将一条记录以“先临时文件后原子改名”的方式落盘，
84	// 并校验目标文件名此前不存在，保证记录标识不会复用或混写。
85	func writeRecord(slotDir string, e *envelope) error {
86		final := recordPath(slotDir, e.ID)
87		data, err := json.MarshalIndent(e, "", "  ")
88		if err != nil {
89			return err
90		}
91	
92		// O_EXCL：即便极小概率撞到重复 ID，也绝不会覆盖别的记录。
93		f, err := os.OpenFile(final+".tmp",
94			os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
95		if err != nil {
96			return err
97		}
98		tmpName := f.Name()
99		clean := true
100		defer func() {
101			if clean {
102				os.Remove(tmpName)
103			}
104		}()
105	
106		if _, err := f.Write(data); err != nil {
107			f.Close()
108			return err
109		}
110		if err := f.Sync(); err != nil {
111			f.Close()
112			return err
113		}
114		if err := f.Close(); err != nil {
115			return err
116		}
117		if err := os.Rename(tmpName, final); err != nil {
118			return err
119		}
120		clean = false
121		if err := syncDir(filepath.Dir(final)); err != nil {
122			return err
123		}
124		return nil
125	}
