127	// loadRecord 读取并解析一条记录文件，但不做校验。
128	//
129	// 解析前先做文本编码检查：encoding/json 会把记录中的无效 UTF-8 字节和
130	// 字符串值、对象键里不成对的 Unicode 代理项转义悄悄改写成替换字符“�”，
131	// 随后才做内容校验——若原记录本就含有合法的“�”，改写后的文本甚至可能
132	// 仍通过校验和检查，文件损坏便被掩盖。因此无效字节与不成对的代理项转义
133	// 必须在解析前按原始字节拒绝，整条记录视为损坏，绝不用替换字符补齐后
134	// 继续交付。
135	//
136	// 解析后还要检查同一对象内的名称是否重复出现：encoding/json 对同名字段
137	// 静默采用后一个值，只要解码后的内容与校验和匹配，一份内部自相矛盾的
138	// 记录（例如先写一个负的时间片、再用同名字段写回合法值）就会被当作完好
139	// 记录交付。因此同一对象内任何名称出现第二次，无论两个值是否相同、采用
140	// 后一个值后的世界是否合法、校验和是否匹配，整条记录都视为损坏。
141	//
142	// 对会解码到结构体固定字段的对象，判定与 encoding/json 的字段选择一致：
143	// 它对结构体字段名做大小写不敏感匹配，所以 "Time" 与 "time"、"ID" 与
144	// "id" 读写的是同一个固定字段，只换大小写就算重复，不能让后一个值遮住
145	// 前一个值。名称到数值的携带上限是 map：其键是实际角色标识而非固定字段，
146	// "hero" 与 "HERO" 是两个角色，仍按还原后的精确名称区分。
147	func loadRecord(path string) (*envelope, error) {
148		f, err := os.Open(path)
149		if err != nil {
150			return nil, err
151		}
152		defer f.Close()
153		data, err := io.ReadAll(f)
154		if err != nil {
155			return nil, err
156		}
157		if err := checkRecordText(data); err != nil {
158			return nil, err
159		}
160		var e envelope
161		if err := json.Unmarshal(data, &e); err != nil {
162			return nil, fmt.Errorf("记录无法解析: %w", err)
163		}
164		if err := checkDuplicateNames(data); err != nil {
165			return nil, err
166		}
167		return &e, nil
168	}
