170	// recordObjectKind 标记记录中一类 JSON 对象按何种方式判定名称重复。
171	type recordObjectKind int
172	
173	const (
174		// 以下对象解码到结构体：键是结构体的固定字段名，与 encoding/json 的
175		// 字段选择相同，按大小写不敏感方式判定是否落到同一字段。
176		objEnvelope recordObjectKind = iota
177		objState
178		objRules
179		objEdge
180		objCharacter
181		objCharacterItem
182		// objMap 解码到 map（携带上限）：键是实际角色标识而非固定字段，必须
183		// 按还原后的精确名称区分，hero 与 HERO 是两个角色。
184		objMap
185		// objUnknown 是不属于记录结构的多余对象（如被忽略的未知字段值），
186		// 其中没有登记的固定字段，键按还原后的精确名称判定。
187		objUnknown
188	)
189	
190	// recordFieldNames 列出每类结构体对象登记的固定字段名（Go 字段名），用于
191	// 把 JSON 键按 encoding/json 的大小写不敏感规则归并到它会读取的字段上。
192	var recordFieldNames = func() map[recordObjectKind][]string {
193		m := make(map[recordObjectKind][]string, len(recordSchema))
194		for kind, fields := range recordSchema {
195			names := make([]string, 0, len(fields))
196			for name := range fields {
197				names = append(names, name)
198			}
199			m[kind] = names
200		}
201		return m
202	}()
203	
204	// fieldIdentity 返回一个结构体对象内 JSON 键 key 的重复判定身份：若它会被
205	// encoding/json 读取为某个固定字段（大小写不敏感，含 Unicode 转义还原后
206	// 的写法），身份就是该字段名；否则 key 不对应任何固定字段，身份用还原后
207	// 的精确名称，沿用“同一对象内同名出现第二次即损坏”的原有判定。
208	func fieldIdentity(kind recordObjectKind, key string) string {
209		if kind != objMap {
210			for _, name := range recordFieldNames[kind] {
211				if strings.EqualFold(name, key) {
212					return name
213				}
214			}
215		}
216		return key
217	}
218	
219	// recordChildKind 描述某一结构体内某个固定字段值对应的 JSON 容器类型。
220	type recordChildKind struct {
221		ch byte // 0 表示标量；'{' 表示对象，'[' 表示数组
222		// child 为 ch=='{' 时给出值对象的类型（结构体或携带上限 map）；
223		// elem 为 ch=='[' 时给出数组元素的对象类型，数组元素是标量时为 0。
224		child recordObjectKind
225		elem  recordObjectKind
226	}
227	
228	// recordSchema 描述记录中会出现的结构体对象及其固定字段，键均为 Go 字段
229	// 名（大写）。表与 envelope 及其引用的类型一一对应；新增固定字段时必须
230	// 同步登记，否则重复检查可能漏判新字段的大小写变体。表中只登记容器类型
231	// 的字段，标量字段只需出现在字段集合里、无需描述其值。
232	var recordSchema = map[recordObjectKind]map[string]recordChildKind{
233		objEnvelope: {
234			"Format":    {},
235			"ID":        {},
236			"Parent":    {},
237			"SlotFirst": {},
238			"Checksum":  {},
239			"State":     {ch: '{', child: objState},
240		},
241		objState: {
242			"Seed":       {},
243			"Rules":      {ch: '{', child: objRules},
244			"Time":       {},
245			"Characters": {ch: '[', elem: objCharacter},
246		},
247		objRules: {
248			"Version":     {},
249			"Locations":   {},
250			"Edges":       {ch: '[', elem: objEdge},
251			"ItemKinds":   {},
252			"CarryLimits": {ch: '{', child: objMap}, // 解码到 map[string]int
253		},
254		objEdge: {
255			"From": {},
256			"To":   {},
257		},
258		objCharacter: {
259			"ID":       {},
260			"Location": {},
261			"Items":    {ch: '[', elem: objCharacterItem},
262		},
263		objCharacterItem: {
264			"Item":  {},
265			"Count": {},
266		},
267		// objMap 没有固定字段；其中的键是角色标识，不登记字段名。
268		objMap: {},
269	}
270	
271	// checkDuplicateNames 检查 JSON 文本中同一对象内的名称是否重复出现。
272	//
273	// 名称按 JSON 转义还原后的字符串比较：直接写出的名称与表示同一名称的
274	// Unicode 转义（如 "ID" 与写作转义形式的同一名称）视为同一名称，不能
275	// 借此绕过限制。
276	//
277	// 对解码到结构体的对象（记录顶层、世界状态、规则、道路、角色、物品条目），
278	// 判定与 encoding/json 选择字段的方式一致：固定字段名大小写不敏感，只要
279	// 两个名称会被读取为同一个固定字段（如 "Time" 与 "time"），即使拼写大小
280	// 写不同、两个值相同或先后顺序不同，也算重复。解码到 map 的携带上限对象
281	// 不同：其中的键是实际角色标识，按还原后的精确名称比较，hero 与 HERO 是
282	// 两个角色，不能合并或误报。
283	//
284	// 判定严格按对象边界：两个不同对象各自使用相同名称是正常的（例如两个物品
285	// 条目各自有数量字段），只有同一对象内名称第二次出现才报错；字符串值中的
286	// 文字与标点不算对象名称。记录文本已经通过 json.Unmarshal 解析，这里只做
287	// 重复名称判定，语法问题不再出现。
288	func checkDuplicateNames(data []byte) error {
289		dec := json.NewDecoder(bytes.NewReader(data))
290		// UseNumber 避免数值范围差异：这里只关心对象结构与名称，不解释数值。
291		dec.UseNumber()
292		// frame 描述解析栈中的一层容器。对象记录已见过的名称身份：结构体对象
293		// 用 fieldIdentity 归并到它会读取到的固定字段名，map 与多余对象用还原
294		// 后的精确键；expectKey 跟踪下一个 token 是否为键。数组只占位并记录其
295		// 元素的对象类型，其中的字符串是值而不是名称。
296		type frame struct {
297			isObj      bool
298			kind       recordObjectKind
299			elem       recordObjectKind // 仅数组帧使用：元素是对象时的对象类型
300			elemValid  bool             // 仅数组帧使用：该数组元素是否登记为对象
301			seen       map[string]bool
302			expectKey  bool
303			pendingKey string // 刚读入、其值尚未开始的键（对象帧使用）
304		}
305		// fieldKind 返回该对象的字段 field（大小写不敏感）在其值容器为 want
306		// （'{' 或 '['）时登记的子对象类型。
307		fieldKind := func(f *frame, field string, want byte) (recordObjectKind, bool) {
308			d, ok := recordSchema[f.kind][fieldIdentity(f.kind, field)]
309			if !ok || d.ch != want {
310				return 0, false
311			}
312			if want == '{' {
313				return d.child, true
314			}
315			return d.elem, d.elem != 0
316		}
317		var stack []*frame
318		pushObject := func(kind recordObjectKind) {
319			stack = append(stack, &frame{
320				isObj:     true,
321				kind:      kind,
322				seen:      make(map[string]bool),
323				expectKey: true,
324			})
325		}
326		// 一个值（标量或容器）结束后，父对象等待下一个键。
327		markValueDone := func() {
328			if n := len(stack); n > 0 && stack[n-1].isObj {
329				stack[n-1].expectKey = true
330			}
331		}
332		for {
333			tok, err := dec.Token()
334			if err != nil {
335				// 文本已通过 json.Unmarshal，正常只会遇到 io.EOF；其余
336				// 情况不在这里报告。
337				return nil
338			}
339			if n := len(stack); n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
340				if d, ok := tok.(json.Delim); ok && d == '}' {
341					stack = stack[:n-1]
342					continue
343				}
344				key, ok := tok.(string)
345				if !ok {
346					return nil
347				}
348				parent := stack[n-1]
349				// 结构体按它会读取到的固定字段归并大小写变体；携带上限 map
350				// 与多余对象保留还原后的精确名称。
351				identity := fieldIdentity(parent.kind, key)
352				if parent.seen[identity] {
353					if parent.kind == objMap || parent.kind == objUnknown {
354						return fmt.Errorf("同一对象内名称 %q 重复出现", key)
355					}
356					return fmt.Errorf("同一对象内名称 %q 重复出现：与先前某名称会被读取为同一个固定字段", key)
357				}
358				parent.seen[identity] = true
359				parent.expectKey = false
360				parent.pendingKey = key
361				continue
362			}
363			d, isDelim := tok.(json.Delim)
364			if !isDelim {
365				markValueDone()
366				continue
367			}
368			switch d {
369			case '{':
370				kind := objUnknown
371				if n := len(stack); n > 0 {
372					parent := stack[n-1]
373					switch {
374					case parent.isObj:
375						// 父对象键对应的值对象：类型由模式表给出（如 State、
376						// Rules 是结构体，CarryLimits 是 map）。未登记的是被
377						// 结构体忽略的多余字段，按未知对象处理。
378						if k, ok := fieldKind(parent, parent.pendingKey, '{'); ok {
379							kind = k
380						}
381					case parent.elemValid:
382						// 数组中的对象元素：结构体类型由数组帧登记。
383						kind = parent.elem
384					}
385				} else {
386					// 根对象是记录信封。
387					kind = objEnvelope
388				}
389				markValueDone()
390				pushObject(kind)
391			case '[':
392				var elem recordObjectKind
393				var valid bool
394				if n := len(stack); n > 0 && stack[n-1].isObj {
395					parent := stack[n-1]
396					if d, ok := recordSchema[parent.kind][fieldIdentity(parent.kind, parent.pendingKey)]; ok && d.ch == '[' {
397						elem, valid = d.elem, d.elem != 0
398					}
399				}
400				markValueDone()
401				stack = append(stack, &frame{elem: elem, elemValid: valid})
402			case '}', ']':
403				stack = stack[:len(stack)-1]
404				markValueDone()
405			}
406		}
407	}
408	
409	// checkRecordText 校验记录文件原始字节的文本编码，规则见 checkJSONText。
410	func checkRecordText(data []byte) error {
411		return checkJSONText(data, "记录")
412	}
413	
414	// checkSlotPointerText 校验槽指针文件原始字节的文本编码，规则见
415	// checkJSONText。槽指针与记录一样会被 encoding/json 悄悄改写损坏文本，
416	// 因此必须在解析前按原始字节拒绝。
417	func checkSlotPointerText(data []byte) error {
418		return checkJSONText(data, "槽指针")
419	}
420	
421	// checkJSONText 校验 JSON 文本原始字节的文本编码：文本必须是合法
422	// UTF-8；字符串值与对象键中的 \uXXXX 转义若是代理项，必须完整配对——
423	// 高位代理项（D800–DBFF）后必须紧接一个低位代理项转义（DC00–DFFF），
424	// 低位代理项不得单独出现。合法内容不受影响：真实存在的“�”、正确配对
425	// 的代理项转义与同一字符的合法转义写法都照常接受；已经转义的反斜杠
426	// （\\）其后的 uD800 只是普通文字，不是代理项转义。what 是出错原因中
427	// 对这份文本的称呼（如“记录”“槽指针”）。
428	func checkJSONText(data []byte, what string) error {
429		if !utf8.Valid(data) {
430			return fmt.Errorf("%s包含无效 UTF-8 字节，文本编码损坏", what)
431		}
432		// 只需定位字符串字面量并检查其中的 \u 转义；JSON 其余部分的合法性
433		// 由 json.Unmarshal 判断。data 已是合法 UTF-8，多字节字符中不可能
434		// 出现 '"' 或 '\\' 字节。
435		i := 0
436		for i < len(data) {
437			if data[i] != '"' {
438				i++
439				continue
440			}
441			i++ // 进入字符串字面量
442			for i < len(data) {
443				c := data[i]
444				if c == '"' {
445					i++
446					break
447				}
448				if c != '\\' {
449					i++
450					continue
451				}
452				// 转义序列：\\ 是已转义的反斜杠，其后的 uD800 只是普通文字。
453				i++
454				if i >= len(data) {
455					break // 截断的转义由 json.Unmarshal 报解析错误
456				}
457				esc := data[i]
458				i++
459				if esc != 'u' {
460					continue
461				}
462				if i+4 > len(data) {
463					break // 截断的转义由 json.Unmarshal 报解析错误
464				}
465				v, ok := hex4(data[i : i+4])
466				i += 4
467				if !ok {
468					continue // 非法十六进制由 json.Unmarshal 报解析错误
469				}
470				switch {
471				case v >= 0xD800 && v <= 0xDBFF:
472					// 高位代理项必须紧接一个低位代理项转义才完整。
473					if i+6 <= len(data) && data[i] == '\\' && data[i+1] == 'u' {
474						if lo, ok := hex4(data[i+2 : i+6]); ok && lo >= 0xDC00 && lo <= 0xDFFF {
475							i += 6
476							continue
477						}
478					}
479					return fmt.Errorf("%s包含未配对的高位代理项转义 \\u%04X，Unicode 转义损坏", what, v)
480				case v >= 0xDC00 && v <= 0xDFFF:
481					return fmt.Errorf("%s包含单独出现的低位代理项转义 \\u%04X，Unicode 转义损坏", what, v)
482				}
483			}
484		}
485		return nil
486	}
487	
488	// hex4 解析 4 位十六进制数字（\uXXXX 转义的码位部分）。
489	func hex4(b []byte) (int, bool) {
490		v := 0
491		for _, c := range b {
492			v <<= 4
493			switch {
494			case c >= '0' && c <= '9':
495				v |= int(c - '0')
496			case c >= 'a' && c <= 'f':
497				v |= int(c-'a') + 10
498			case c >= 'A' && c <= 'F':
499				v |= int(c-'A') + 10
500			default:
501				return 0, false
502			}
503		}
504		return v, true
505	}
506	
507	func syncDir(dir string) error {
508		d, err := os.Open(dir)
509		if err != nil {
510			return err
511		}
512		defer d.Close()
513		return d.Sync()
514	}
515	
516	// writeAtomic 把 data 写入 dir 下的 name：同目录临时文件、fsync、
517	// 原子改名，保证崩溃后只会看到旧文件或新文件。
518	func writeAtomic(dir, name string, data []byte) error {
519		tmp := filepath.Join(dir, ".tmp-"+name+"-"+randomSuffix())
520		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
521		if err != nil {
522			return err
523		}
524		clean := true
525		defer func() {
526			if clean {
527				os.Remove(tmp)
528			}
529		}()
530		if _, err := f.Write(data); err != nil {
531			f.Close()
532			return err
533		}
534		if err := f.Sync(); err != nil {
535			f.Close()
536			return err
537		}
538		if err := f.Close(); err != nil {
539			return err
540		}
541		final := filepath.Join(dir, name)
542		if err := os.Rename(tmp, final); err != nil {
543			return err
544		}
545		clean = false
546		return syncDir(dir)
547	}
548	
549	func randomSuffix() string {
550		var b [8]byte
551		_, _ = rand.Read(b[:])
552		return hex.EncodeToString(b[:])
553	}
554

