167	// TestCaseVariantDuplicateBrowseAndRecover 含大小写变体重复字段的最新记录
168	// 在历史浏览中被略过；恢复读取与恢复预览越过它，选择本槽最近一份完好且
169	// 版本可接受的记录，全程不修补文件、不切换槽指向。
170	func TestCaseVariantDuplicateBrowseAndRecover(t *testing.T) {
171		a, _ := newTestArchive(t)
172		ids := saveN(t, a, "s", 2) // r2(time 2) r1(time 1) r0(time 0)
173		rewriteRecordText(t, a, ids[0], `"Time": 2,`, `"Time": -1, "time": 2,`)
174		before := recordFileBytes(t, a, ids[0])
175	
176		infos, err := a.History("s")
177		if err != nil {
178			t.Fatalf("History: %v", err)
179		}
180		if len(infos) != 2 || infos[0].ID != ids[1] || infos[1].ID != ids[2] {
181			t.Fatalf("含大小写重复字段的记录应被略过，其余按次序列出: %+v", infos)
182		}
183	
184		rec, err := a.RecoverLatest("s", []string{"v1"})
185		if err != nil {
186			t.Fatalf("应恢复最近一份完好记录: %v", err)
187		}
188		if rec.ID != ids[1] || rec.State.Time != 1 {
189			t.Fatalf("应恢复 %s（时间片 1），得到 %s（时间片 %d）", ids[1], rec.ID, rec.State.Time)
190		}
191		pv, err := a.PreviewRecovery("s", []string{"v1"})
192		if err != nil {
193			t.Fatalf("PreviewRecovery: %v", err)
194		}
195		if pv.Current != ids[0] || pv.Source != ids[1] {
196			t.Fatalf("预览应为 current=%s source=%s，得到 current=%s source=%s",
197				ids[0], ids[1], pv.Current, pv.Source)
198		}
199	
200		// 其余记录也带上大小写变体重复字段后，恢复与预览返回不可恢复错误。
201		rewriteRecordText(t, a, ids[1], `"Time": 1,`, `"Time": -1, "time": 1,`)
202		rewriteRecordText(t, a, ids[2], `"Time": 0,`, `"Time": -1, "time": 0,`)
203		if _, err := a.RecoverLatest("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
204			t.Fatalf("全部损坏时应不可恢复，得到 %T: %v", err, err)
205		}
206		if infos, err := a.History("s"); err != nil || len(infos) != 0 {
207			t.Fatalf("全部损坏时历史应为成功的空列表: %+v err=%v", infos, err)
208		}
209	
210		if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
211			t.Fatal("浏览/恢复改写了含重复字段的记录")
212		}
213		if p, err := a.readSlotPointerLocked("s"); err != nil || p.Latest != ids[0] {
214			t.Fatalf("槽指向不应改变: %+v err=%v", p, err)
215		}
216	}
