58	// Archive 是一个本地存档目录句柄。多个进程或多个实例可以同时打开
59	// 同一目录；所有写入通过目录内的 flock 串行化。
60	type Archive struct {
61		dir string
62	}
63	
64	const (
65		markerName  = "archive.json"
66		recordsName = "records"
67		slotsName   = "slots"
68	)
