70	// Create 在指定目录建立新的存档。目录会被创建；若该目录已经是一个
71	// 存档则返回错误，以免覆盖已有数据。
72	//
73	// 创建有明确的结果：要么完整成功并返回可立即使用的句柄，要么返回
74	// 错误且不返回句柄。准备必要目录、写入存档标记或建立锁文件时出错，
75	// 都会把指明失败操作与位置的错误交给调用方，并撤回本次创建已产生的
76	// 标记、锁文件与子目录——回退只限本次新增的内容：目录里原有的文件与
77	// 子目录（包括原本就存在、可直接使用的空 records/slots 子目录）以及
78	// 调用前已存在的目标目录本身都保持原样。因此失败后排除障碍即可用
79	// 同一路径重新创建，不会被上一次失败留下的标记拒绝。
80	func Create(dir string) (_ *Archive, err error) {
81		// 本次调用新产生的内容，失败时按相反顺序撤回；调用前已存在的
82		// 任何内容都不在撤回范围内。
83		var created []string
84		defer func() {
85			if err != nil {
86				for i := len(created) - 1; i >= 0; i-- {
87					os.Remove(created[i])
88				}
89			}
90		}()
91	
92		// 目标目录在调用前已存在时保留它（包括失败回退时）；不存在才
93		// 由本次创建建立，并纳入回退范围。
94		if _, statErr := os.Stat(dir); statErr != nil {
95			if !errors.Is(statErr, os.ErrNotExist) {
96				return nil, fmt.Errorf("检查存档目录 %s: %w", dir, statErr)
97			}
98			if err := os.MkdirAll(dir, 0o755); err != nil {
99				return nil, fmt.Errorf("建立存档目录 %s: %w", dir, err)
100			}
101			created = append(created, dir)
102		}
103	
104		markerPath := filepath.Join(dir, markerName)
105		f, err := os.OpenFile(markerPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
106		if err != nil {
107			if errors.Is(err, os.ErrExist) {
108				// 已有存档：原样保留既有标记（即使它无法解析），不覆盖，
109				// 也不借回退删除；此时本次尚未产生任何新内容。
110				return nil, &ConflictError{Reason: "目录已是一个存档: " + dir}
111			}
112			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
113		}
114		created = append(created, markerPath)
115		markerData, _ := json.Marshal(archiveMarker{Format: archiveFormatVersion})
116		if _, err := f.Write(markerData); err != nil {
117			f.Close()
118			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
119		}
120		if err := f.Close(); err != nil {
121			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
122		}
123	
124		for _, sub := range []string{recordsName, slotsName} {
125			subPath := filepath.Join(dir, sub)
126			if fi, statErr := os.Stat(subPath); statErr == nil {
127				if !fi.IsDir() {
128					return nil, fmt.Errorf("建立存档子目录 %s: 位置已被同名文件占用", subPath)
129				}
130				// 原本就存在的子目录直接沿用，回退时保留。
131				continue
132			} else if !errors.Is(statErr, os.ErrNotExist) {
133				return nil, fmt.Errorf("检查存档子目录 %s: %w", subPath, statErr)
134			}
135			if err := os.Mkdir(subPath, 0o755); err != nil {
136				return nil, fmt.Errorf("建立存档子目录 %s: %w", subPath, err)
137			}
138			created = append(created, subPath)
139		}
140	
141		// 预先建立锁文件并同步目录，使之后的打开更稳妥。锁位置已被占用
142		// （例如已是一个目录）时明确报错，而不是留到首次保存才失败。
143		lockPath := filepath.Join(dir, "lock")
144		_, lockStatErr := os.Stat(lockPath)
145		lockExisted := lockStatErr == nil
146		if lockStatErr != nil && !errors.Is(lockStatErr, os.ErrNotExist) {
147			return nil, fmt.Errorf("检查存档锁文件 %s: %w", lockPath, lockStatErr)
148		}
149		lf, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o600)
150		if err != nil {
151			return nil, fmt.Errorf("建立存档锁文件 %s: %w", lockPath, err)
152		}
153		if err := lf.Close(); err != nil {
154			return nil, fmt.Errorf("建立存档锁文件 %s: %w", lockPath, err)
155		}
156		if !lockExisted {
157			created = append(created, lockPath)
158		}
159	
160		if err := syncDir(dir); err != nil {
161			return nil, fmt.Errorf("同步存档目录 %s: %w", dir, err)
162		}
163		return &Archive{dir: dir}, nil
164	}
165	
166	// Open 打开一个此前由 Create 建立的存档目录。
167	func Open(dir string) (*Archive, error) {
168		path := filepath.Join(dir, markerName)
169		f, err := os.Open(path)
170		if err != nil {
171			if errors.Is(err, os.ErrNotExist) {
172				return nil, &NotFoundError{}
173			}
174			return nil, err
175		}
176		defer f.Close()
177		var m archiveMarker
178		if err := json.NewDecoder(f).Decode(&m); err != nil {
179			return nil, &CorruptError{Reason: "存档标记无法解析"}
180		}
181		if m.Format != archiveFormatVersion {
182			return nil, &CorruptError{Reason: "不支持的存档格式版本"}
183		}
184		for _, sub := range []string{recordsName, slotsName} {
185			if fi, err := os.Stat(filepath.Join(dir, sub)); err != nil || !fi.IsDir() {
186				return nil, &CorruptError{Reason: "存档目录结构不完整: 缺少 " + sub}
187			}
188		}
189		return &Archive{dir: dir}, nil
190	}
