199	// validSlotName 拒绝空名以及可能逃逸 slots 目录的名字。
200	func validSlotName(slot string) bool {
201		if slot == "" || slot == "." || slot == ".." {
202			return false
203		}
204		if filepath.IsAbs(slot) {
205			return false
206		}
207		for _, r := range slot {
208			if r == '/' || r == '\\' || r == 0 {
209				return false
210			}
211		}
212		return filepath.Clean(slot) == slot
213	}
