215	// readSlotPointerLocked 在调用方已持锁的前提下读取并解析槽指针文件。
216	//
217	// 解析前先做文本编码检查（与记录文件同一套规则）：原始字节含无效 UTF-8，
218	// 或字符串中的 Unicode 代理项转义未正确配对（孤立的低位代理项、高位代理项
219	// 后没有紧接低位代理项），无论出现在字段名、当前标识、历史标识还是其他
220	// 字符串中，整份指针都按损坏拒绝，返回带槽名的 *CorruptError——encoding/json
221	// 会把这些内容悄悄改写成替换字符“�”后继续解码，绝不允许用改写后的标识
222	// 读取当前记录或浏览历史，也不按指针里剩余的完好部分继续寻找旧记录。真实
223	// 写入的“�”、中文、正确配对的代理项转义，以及转义后的反斜杠后跟普通文字
224	// uD800 都是合法文本，照常接受。
225	//
226	// 除 JSON 语法外，还要检查顶层对象内 latest 与 history 两个字段是否各自
227	// 重复出现：encoding/json 对同一字段静默采用后一个值（history 甚至整体
228	// 替换前一份），于是读到的当前世界或可浏览的历史会随字段书写次序变化。
229	// 出现这种歧义时整个指针按损坏拒绝，绝不选其中一个值继续；判定方式与
230	// encoding/json 选择字段一致——完全同名、只改大小写的写法，以及 Unicode
231	// 转义还原后对应同一字段的写法都算同一字段重复，两个值相同、其中一个为
232	// 空、后一份历史更完整或所指记录校验通过都不豁免，交换先后次序同样损坏。
233	// 名称只出现一次时，本就可接受的大小写与转义写法照常读取；缺少 history
234	// 是旧版本合法指针，不算重复。history 数组内部同一记录标识重复出现属于
235	// 另一回事，沿用既有的去重与次序规则。
236	func (a *Archive) readSlotPointerLocked(slot string) (slotPointer, error) {
237		data, err := os.ReadFile(a.slotPath(slot))
238		if err != nil {
239			if errors.Is(err, os.ErrNotExist) {
240				return slotPointer{}, &NotFoundError{Slot: slot}
241			}
242			return slotPointer{}, err
243		}
244		// 文本编码检查先于一切解析：encoding/json 会把无效 UTF-8 字节与不成对
245		// 的代理项转义改写成替换字符后继续，损坏的字段名或记录标识会被掩盖。
246		if err := checkSlotPointerText(data); err != nil {
247			return slotPointer{}, &CorruptError{Slot: slot, Reason: err.Error()}
248		}
249		// 重复字段检查只依赖 JSON 语法结构（键与容器边界），不依赖值类型，因此
250		// 先于 Unmarshal 的类型错误：即使重复字段的某个值类型不对、解码失败，
251		// 也要明确报字段重复，而不是笼统的无法解析。
252		if dup, ok := duplicatePointerField(data); ok {
253			return slotPointer{}, &CorruptError{
254				Slot:   slot,
255				Reason: fmt.Sprintf("槽指针字段 %q 重复出现：同一对象内有两个名称会被读取为该字段，槽指针含义有歧义", dup),
256			}
257		}
258		var p slotPointer
259		if err := json.Unmarshal(data, &p); err != nil {
260			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针无法解析"}
261		}
262		if p.Latest == "" {
263			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针为空"}
264		}
265		return p, nil
266	}
267	
268	// duplicatePointerField 检查槽指针 JSON 顶层对象内 latest、history 两个
269	// 固定字段是否各自重复出现。槽指针是只有这两个字段的扁平对象，检查只需
270	// 遍历顶层键、不进入任何值容器；history 数组元素是值而非字段名，数组内
271	// 同一记录标识重复出现不在此判定。
272	//
273	// 键按 JSON 转义还原后的字符串与字段标签做大小写不敏感匹配，与
274	// encoding/json 对结构体字段的选择一致：因此 "latest" 与 "Latest"、
275	// "history" 与写作 Unicode 转义形式的同一名称（如 "latest"）都会
276	// 归并到同一字段，任一字段第二次出现即返回该字段标签。文本已通过
277	// json.Unmarshal，这里不会再遇到语法问题。
278	func duplicatePointerField(data []byte) (string, bool) {
279		dec := json.NewDecoder(bytes.NewReader(data))
280		dec.UseNumber()
281		tok, err := dec.Token()
282		if err != nil {
283			return "", false
284		}
285		d, ok := tok.(json.Delim)
286		if !ok || d != '{' {
287			return "", false
288		}
289		seen := map[string]bool{}
290		for {
291			tok, err := dec.Token()
292			if err != nil {
293				return "", false
294			}
295			if d, ok := tok.(json.Delim); ok && d == '}' {
296				return "", false
297			}
298			key, ok := tok.(string)
299			if !ok {
300				return "", false
301			}
302			field := ""
303			switch {
304			case strings.EqualFold(key, "latest"):
305				field = "latest"
306			case strings.EqualFold(key, "history"):
307				field = "history"
308			}
309			if field != "" {
310				if seen[field] {
311					return field, true
312				}
313				seen[field] = true
314			}
315			// 跳过该键对应的值（标量直接取下一个 token；数组或对象整体跳过），
316			// 使下一轮仍停留在顶层键或右花括号上。
317			if err := skipJSONValue(dec); err != nil {
318				return "", false
319			}
320		}
321	}
322	
323	// skipJSONValue 消费刚读入键之后的那一个 JSON 值：标量只需再读一个 token，
324	// 数组或对象按配对的分隔符整体跳过，不把其中内容当作顶层字段。
325	func skipJSONValue(dec *json.Decoder) error {
326		tok, err := dec.Token()
327		if err != nil {
328			return err
329		}
330		d, ok := tok.(json.Delim)
331		if !ok {
332			return nil
333		}
334		var open, close byte
335		switch d {
336		case '{':
337			open, close = '{', '}'
338		case '[':
339			open, close = '[', ']'
340		default:
341			return nil
342		}
343		depth := 1
344		for depth > 0 {
345			t, err := dec.Token()
346			if err != nil {
347				return err
348			}
349			if td, ok := t.(json.Delim); ok {
350				switch byte(td) {
351				case open:
352					depth++
353				case close:
354					depth--
355				}
356			}
357		}
358		return nil
359	}
360	
361	// readLatestLocked 在调用方已持锁的前提下读取槽当前最新记录标识。
362	func (a *Archive) readLatestLocked(slot string) (RecordID, error) {
363		p, err := a.readSlotPointerLocked(slot)
364		if err != nil {
365			return "", err
366		}
367		return p.Latest, nil
368	}
