370	// Save 在存档中保存一个世界。
371	//
372	// 首次保存会创建同名存档槽；槽名已存在时返回 *ConflictError。
373	// 成功后返回新记录的标识，记录包含完整世界数据，且没有父记录。槽位上已
374	// 有指针但无法解析或顶层字段重复（含义有歧义）时返回 *CorruptError，不把
375	// 该槽当作可写入的新槽或旧槽处理，也不创建任何记录。
376	func (a *Archive) Save(slot string, w *World) (RecordInfo, error) {
377		if !validSlotName(slot) {
378			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
379		}
380		st := w.Snapshot()
381	
382		lock, err := acquireLock(a.dir)
383		if err != nil {
384			return RecordInfo{}, err
385		}
386		defer lock.release()
387	
388		// 持锁后再次确认槽不存在。
389		if _, err := a.readLatestLocked(slot); err == nil {
390			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
391		} else if !errors.As(err, new(*NotFoundError)) {
392			return RecordInfo{}, err
393		}
394	
395		id, err := newRecordID()
396		if err != nil {
397			return RecordInfo{}, err
398		}
399		env := &envelope{
400			Format:    recordFormatVersion,
401			ID:        id,
402			SlotFirst: true,
403			State:     st,
404		}
405		env.Checksum = computeChecksum(env)
406		if err := writeRecord(a.dir, env); err != nil {
407			return RecordInfo{}, err
408		}
409		if err := a.createSlotPointer(slot, id); err != nil {
410			return RecordInfo{}, err
411		}
412		return RecordInfo{ID: id, SlotFirst: true, Version: st.Rules.Version}, nil
413	}
414	
415	// createSlotPointer 以“临时文件写全 + os.Link 原子建立”的方式创建槽
416	// 指针：Link 在目标已存在时失败，因此重名会被明确拒绝，同时崩溃后
417	// 要么没有该槽，要么指向一份完整记录，绝不会留下半写的指针。新槽的
418	// 历史索引只含其首条记录本身——分支槽不会把来源槽的记录计入候选。
419	func (a *Archive) createSlotPointer(slot string, id RecordID) error {
420		slotsDir := filepath.Join(a.dir, slotsName)
421		final := a.slotPath(slot)
422		data, _ := json.MarshalIndent(slotPointer{
423			Latest:  id,
424			History: []RecordID{id},
425		}, "", "  ")
426	
427		tmp := filepath.Join(slotsDir, ".new-"+slot+"-"+randomSuffix()+".tmp")
428		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
429		if err != nil {
430			return err
431		}
432		if _, err := f.Write(data); err != nil {
433			f.Close()
434			os.Remove(tmp)
435			return err
436		}
437		if err := f.Sync(); err != nil {
438			f.Close()
439			os.Remove(tmp)
440			return err
441		}
442		if err := f.Close(); err != nil {
443			os.Remove(tmp)
444			return err
445		}
446		if err := os.Link(tmp, final); err != nil {
447			os.Remove(tmp)
448			if errors.Is(err, os.ErrExist) {
449				return &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
450			}
451			return err
452		}
453		os.Remove(tmp)
454		return syncDir(slotsDir)
455	}
456	
457	// Replace 用世界当前状态覆盖槽的最新记录。
458	//
459	// expected 必须是调用方此前读到的记录标识，并且它仍是该槽最新记录，
460	// 写入才会发生；否则返回 *ConflictError——即使该标识对应的旧文件恰好
461	// 已损坏或被删除，过期请求也只报冲突，不改报文件错误。标识匹配时还要
462	// 确认这条当前记录本身可正常读取：文件缺失返回 *NotFoundError；格式版本
463	// 不受支持、截断、校验和不匹配、世界状态不合法或父记录缺失返回
464	// *CorruptError。绝不用
465	// 调用方传入的完整世界掩盖当前记录的问题，也不自动改选较老记录为父。
466	// 新记录的父记录就是被覆盖的那次记录。同一目录下并发覆盖同一父记录时
467	// 只有一个成功。被拒绝的覆盖不改变槽指向、历史与任何已有记录。槽指针
468	// 无法解析，或顶层 latest/history 字段重复（含义有歧义）时按 *CorruptError
469	// 拒绝：无法确定当前记录与待承接的历史，不保存新记录，也不自动修补指针。
470	func (a *Archive) Replace(slot string, w *World, expected RecordID) (RecordInfo, error) {
471		if !validSlotName(slot) {
472			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
473		}
474		if expected == "" {
475			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "覆盖必须提供所依据的记录标识"}
476		}
477		st := w.Snapshot()
478	
479		lock, err := acquireLock(a.dir)
480		if err != nil {
481			return RecordInfo{}, err
482		}
483		defer lock.release()
484	
485		pointer, err := a.readSlotPointerLocked(slot)
486		if err != nil {
487			return RecordInfo{}, err
488		}
489		if pointer.Latest != expected {
490			return RecordInfo{}, &ConflictError{
491				Slot:   slot,
492				Reason: "所依据的记录已不是该槽最新记录",
493			}
494		}
495	
496		// 标识匹配后，当前记录本身必须可正常读取：格式受支持、完整、内容
497		// 校验通过、世界状态合法且父记录关系成立。否则以它为父保存的新记录随后也
498		// 无法读取，等于用调用方传入的完整世界掩盖了当前记录的问题；
499		// 这里沿用与读取路径一致的校验，损坏或缺失时拒绝覆盖，槽指向、
500		// 历史与已有记录保持原样，调用方可改走恢复预览与确认恢复。
501		if _, err := a.loadAndVerifyLocked(expected); err != nil {
502			if ce, ok := err.(*CorruptError); ok {
503				ce.Slot = slot
504			}
505			return RecordInfo{}, err
506		}
507	
508		// 覆盖保存传入世界的快照，以被覆盖的当前记录为父，沿用共同的
509		// 新记录组装、落盘与槽指针提交路径。
510		return a.appendSlotRecordLocked(slotSave{
511			slot:          slot,
512			oldPointer:    pointer,
513			parent:        expected,
514			historyAnchor: expected,
515			state:         st,
516		})
517	}
518	
519	// commitSlotPointerLocked 在记录文件已完整落盘后，原子更新槽指针：指向
520	// 新记录，并把历史索引按保存次序前置新记录。历史索引只在此刻（记录已
521	// 完整生效）才更新，因此残留临时文件与写完但未完成保存的孤儿记录绝不会
522	// 进入恢复候选。
523	func (a *Archive) commitSlotPointerLocked(slot string, oldPointer slotPointer, oldLatest, newID RecordID) error {
524		history, err := a.nextSlotHistoryLocked(oldPointer, oldLatest, newID)
525		if err != nil {
526			return err
527		}
528		return a.persistSlotPointerLocked(slot, slotPointer{Latest: newID, History: history})
529	}
530	
531	// replaceSlotPointer 直接把槽指针指向 id，不附带历史索引。它仅用于测试
532	// 中模拟旧版本或外部写入器留下的指针；生产写入路径一律走
533	// commitSlotPointerLocked 以维护历史索引。
534	func (a *Archive) replaceSlotPointer(slot string, id RecordID) error {
535		return a.persistSlotPointerLocked(slot, slotPointer{Latest: id})
536	}
537	
538	// Branch 从 srcSlot 的指定历史记录 src 分出新槽 dstSlot。
539	//
540	// 新槽的首条记录以 src 为父记录，完整复制当时的种子、规则和状态。
541	// 目标槽名已存在时返回 *ConflictError；目标槽指针无法解析或顶层字段重复
542	// 时返回带目标槽名的 *CorruptError，不覆盖损坏槽也不在其中创建记录。
543	// 源记录必须校验通过，且源槽指针必须可读：无法解析或顶层字段重复时返回
544	// 带源槽名的 *CorruptError，无法确认来源属于该槽就不分出新槽。
545	func (a *Archive) Branch(srcSlot string, src RecordID, dstSlot string) (RecordInfo, error) {
546		if !validSlotName(srcSlot) {
547			return RecordInfo{}, &ConflictError{Slot: srcSlot, Reason: "非法源存档槽名"}
548		}
549		if !validSlotName(dstSlot) {
550			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "非法目标存档槽名"}
551		}
552		if src == "" {
553			return RecordInfo{}, &NotFoundError{Slot: srcSlot}
554		}
555	
556		lock, err := acquireLock(a.dir)
557		if err != nil {
558			return RecordInfo{}, err
559		}
560		defer lock.release()
561	
562		srcEnv, err := a.loadAndVerifyLocked(src)
563		if err != nil {
564			return RecordInfo{}, err
565		}
566		// 确认源记录确实属于源槽的历史链，避免拿别的槽的记录冒充分支源。
567		if err := a.assertInSlotHistoryLocked(srcSlot, src); err != nil {
568			return RecordInfo{}, err
569		}
570		// 目标槽重名拒绝创建。
571		if _, err := a.readLatestLocked(dstSlot); err == nil {
572			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "目标存档槽名已存在"}
573		} else if !errors.As(err, new(*NotFoundError)) {
574			return RecordInfo{}, err
575		}
576	
577		id, err := newRecordID()
578		if err != nil {
579			return RecordInfo{}, err
580		}
581		env := &envelope{
582			Format:    recordFormatVersion,
583			ID:        id,
584			Parent:    src,
585			SlotFirst: true,
586			// 完整复制当时的世界数据；此后两槽各自保存互不影响。
587			State: cloneState(srcEnv.State),
588		}
589		env.Checksum = computeChecksum(env)
590		if err := writeRecord(a.dir, env); err != nil {
591			return RecordInfo{}, err
592		}
593		if err := a.createSlotPointer(dstSlot, id); err != nil {
594			return RecordInfo{}, err
595		}
596		return RecordInfo{
597			ID:        id,
598			Parent:    src,
599			SlotFirst: true,
600			Version:   env.State.Rules.Version,
601		}, nil
602	}
603	
604	// assertInSlotHistoryLocked 确认 id 位于 slot 自身的历史次序中（分支槽
605	// 的历史只含它自己保存成功的记录，不含来源槽记录）。
606	func (a *Archive) assertInSlotHistoryLocked(slot string, id RecordID) error {
607		history, err := a.slotHistoryLocked(slot)
608		if err != nil {
609			return err
610		}
611		for _, cid := range history {
612			if cid == id {
613				return nil
614			}
615		}
616		return &NotFoundError{Slot: slot, Record: id}
617	}
618	
619	// slotHistoryLocked 返回该槽按保存生效次序排列的记录标识（最新在前、
620	// 槽首记录在末尾）。
621	//
622	// 优先使用指针内嵌的历史索引；旧版本指针没有该索引时，在内存中沿
623	// “校验通过”的记录父链回退重建，绝不在读取路径上改写目录。重建在缺失、
624	// 无法解析或校验不过的记录处停止——无法确认归属的更老记录不再使用。
625	// 槽首标记只取自校验通过的信封，因此受损记录里被篡改的父标识或槽首
626	// 标记既不能把遍历引向别的槽，也不能遮住本槽更早的可用记录。
627	func (a *Archive) slotHistoryLocked(slot string) ([]RecordID, error) {
628		p, err := a.readSlotPointerLocked(slot)
629		if err != nil {
630			return nil, err
631		}
632		if len(p.History) > 0 {
633			// 以 Latest 为链头做一次去重规范化，容忍索引中的重复项。
634			return dedupeRecordIDs(append([]RecordID{p.Latest}, p.History...)), nil
635		}
636		return a.rebuildHistoryLocked(p.Latest)
637	}
638	
639	// rebuildHistoryLocked 从 latest 起沿校验通过的父链在内存中重建历史，
640	// 只返回仍能确认属于本槽的记录；在缺失、无法解析或校验不过的记录处停止。
641	func (a *Archive) rebuildHistoryLocked(latest RecordID) ([]RecordID, error) {
642		var chain []RecordID
643		seen := map[RecordID]bool{}
644		cur := latest
645		for cur != "" {
646			if seen[cur] {
647				return nil, &CorruptError{Record: cur, Reason: "历史链出现环"}
648			}
649			seen[cur] = true
650			env, err := a.loadAndVerifyLocked(cur)
651			if err != nil {
652				// 缺失、无法解析或校验不过：无法继续确认更老记录的归属，
653				// 旧历史在此断裂；已确认的部分仍可使用。
654				return chain, nil
655			}
656			chain = append(chain, cur)
657			if env.SlotFirst {
658				return chain, nil
659			}
660			cur = env.Parent
661		}
662		return chain, nil
663	}
664	
665	// dedupeRecordIDs 按首次出现次序去重记录标识。
666	func dedupeRecordIDs(ids []RecordID) []RecordID {
667		seen := map[RecordID]bool{}
668		out := ids[:0]
669		for _, id := range ids {
670			if id == "" || seen[id] {
671				continue
672			}
673			seen[id] = true
674			out = append(out, id)
675		}
676		return out
677	}
678	
679	// persistSlotPointerLocked 以原子改名写出槽指针。
680	func (a *Archive) persistSlotPointerLocked(slot string, p slotPointer) error {
681		data, _ := json.MarshalIndent(p, "", "  ")
682		return writeAtomic(filepath.Join(a.dir, slotsName), slot+".json", data)
683	}
684	
685	// nextSlotHistory 在一次以 oldLatest 为被覆盖/升级记录的成功写入后，
686	// 生成新指针应持有的历史次序：新记录在最前，其余沿用此前已确认属于
687	// 本槽的记录。旧指针无索引时在内存中回退重建（不完整也照样承接），
688	// 从而让旧历史在第一次成功覆盖或升级后获得完整恢复能力。
689	func (a *Archive) nextSlotHistoryLocked(oldPointer slotPointer, oldLatest, newID RecordID) ([]RecordID, error) {
690		base := oldPointer.History
691		if len(base) == 0 {
692			rebuilt, err := a.rebuildHistoryLocked(oldLatest)
693			if err != nil {
694				return nil, err
695			}
696			base = rebuilt
697		}
698		return dedupeRecordIDs(append([]RecordID{newID}, base...)), nil
699	}
700	
701	// Slots 返回所有存档槽名。
702	func (a *Archive) Slots() ([]string, error) {
703		entries, err := os.ReadDir(filepath.Join(a.dir, slotsName))
704		if err != nil {
705			return nil, err
706		}
707		var names []string
708		for _, e := range entries {
709			if e.IsDir() {
710				continue
711			}
712			name := e.Name()
713			if len(name) > 5 && name[len(name)-5:] == ".json" {
714				names = append(names, name[:len(name)-5])
715			}
716		}
717		return names, nil
718	}
