38	// loadAndVerifyLocked 读取记录文件，校验其文本编码（无效 UTF-8 字节与
39	// 不成对的 Unicode 代理项转义一律损坏）、同一对象内是否有重复名称、
40	// 记录格式版本、内容校验和（校验和已包含父记录关系）、父记录是否存在，
41	// 以及世界数据是否自洽。
42	//
43	// 文本编码检查在解析前按原始字节进行：encoding/json 会把无效字节与不成对
44	// 的代理项转义悄悄改写成替换字符“�”，若原记录本就含有合法的“�”，改写后
45	// 的文本甚至可能仍通过校验和检查，因此这类记录即使替换后的世界状态合法、
46	// 校验和匹配、规则版本也被接受，仍按损坏拒绝，绝不用替换字符补齐后交付。
47	//
48	// 同一对象内的名称出现第二次时整条记录视为损坏：encoding/json 对同名字段
49	// 静默采用后一个值，只要解码后的内容与校验和匹配，自相矛盾的记录（例如
50	// 先写负时间片再用同名字段写回合法值）就会被误认作完好。判定按 encoding/json
51	// 选择字段的方式归并名称：对记录、世界状态、规则、道路、角色与物品条目等
52	// 结构体对象，只要两个名称会被读取为同一个固定字段就算重复——含 Unicode
53	// 转义还原后的写法，以及只改大小写的写法（"Time" 与 "time"、"ID" 与
54	// "id"）都不能绕过；两个值相同、交换先后顺序、后一个值让世界合法或校验
55	// 和匹配都不豁免。名称到数值的携带上限对象解码到 map，其键是实际角色
56	// 标识而非固定字段，按还原后的精确名称比较，hero 与 HERO 是两个角色，不
57	// 合并也不误报。不同对象各自使用相同名称不受影响。
58	//
59	// 记录格式只支持 recordFormatVersion：格式编号缺失、为零、为负或为其他
60	// 正整数的记录按损坏处理，即使校验和匹配、世界状态合法、规则版本可被
61	// 调用方接受也不交付——目录能打开不代表每条记录都是当前功能理解的格式。
62	// 格式校验先于内容校验和：校验和载荷的布局本身由格式定义，未知格式的
63	// 记录无法解释其校验语义。格式问题与规则版本分别判断，格式错误一律报
64	// CorruptError，绝不报成 VersionRejectedError。
65	//
66	// 对完整世界状态的认可与 WorldFromState 重建世界保持一致：时间片为负的
67	// 记录属于损坏记录——内容校验和匹配只说明内容完整，规则版本被接受也不
68	// 能使负时间片合法；这样的记录不能被读回，也不能作为恢复或分支的来源。
69	func (a *Archive) loadAndVerifyLocked(id RecordID) (*envelope, error) {
70		env, err := loadRecord(recordPath(a.dir, id))
71		if err != nil {
72			if errors.Is(err, os.ErrNotExist) {
73				return nil, &NotFoundError{Record: id}
74			}
75			return nil, &CorruptError{Record: id, Reason: err.Error()}
76		}
77		if env.ID != id {
78			return nil, &CorruptError{Record: id, Reason: "记录标识与文件名不一致"}
79		}
80		if env.Format != recordFormatVersion {
81			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("不支持的记录格式版本: %d", env.Format)}
82		}
83		if got := computeChecksum(env); got != env.Checksum {
84			return nil, &CorruptError{Record: id, Reason: "内容校验和不匹配（可能已损坏或被改动）"}
85		}
86		// 父记录关系必须落到一个真实存在的记录上。
87		if env.Parent != "" {
88			if _, err := os.Stat(recordPath(a.dir, env.Parent)); err != nil {
89				if errors.Is(err, os.ErrNotExist) {
90					return nil, &CorruptError{Record: id, Reason: "父记录缺失: " + string(env.Parent)}
91				}
92				return nil, err
93			}
94		}
95		// 时间片为负的记录与 WorldFromState 的拒绝保持一致：即使校验和匹配、
96		// 其余状态合法，也按损坏处理，不自动把时间改成零。
97		if env.State.Time < 0 {
98			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("记录中的时间片为负: %d", env.State.Time)}
99		}
100		if err := validateInitialData(InitialData{
101			Seed:       env.State.Seed,
102			Rules:      env.State.Rules,
103			Characters: env.State.Characters,
104		}); err != nil {
105			return nil, &CorruptError{Record: id, Reason: "记录中的世界数据不合法: " + err.Error()}
106		}
107		return env, nil
108	}
