128	// Latest 读取槽当前最新记录。
129	//
130	// acceptedVersions 是调用方明确给出的可接受规则版本集合：记录完好但
131	// 版本不在集合内时返回 *VersionRejectedError；记录损坏（文本编码或
132	// Unicode 转义损坏、同一对象内名称重复、格式版本不受支持、校验和不符、
133	// 父记录缺失、无法解析、时间片为负）时返回 *CorruptError。槽指针本身
134	// 无法解析，或顶层 latest/history 字段重复出现（含义有歧义）时同样返回
135	// 带槽名的 *CorruptError，且不继续读取任何记录。文本损坏、名称重复与
136	// 格式问题都先于版本判断：即使版本不被接受，损坏的记录或指针也报损坏
137	// 而不报版本拒绝。
138	// 读取不会改写存档。
139	func (a *Archive) Latest(slot string, acceptedVersions []string) (Record, error) {
140		if !validSlotName(slot) {
141			return Record{}, &NotFoundError{Slot: slot}
142		}
143		lock, err := acquireSharedLock(a.dir)
144		if err != nil {
145			return Record{}, err
146		}
147		defer lock.release()
148	
149		id, err := a.readLatestLocked(slot)
150		if err != nil {
151			return Record{}, err
152		}
153		env, err := a.loadAndVerifyLocked(id)
154		if err != nil {
155			if ce, ok := err.(*CorruptError); ok {
156				ce.Slot = slot
157			}
158			return Record{}, err
159		}
160		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
161			return Record{}, &VersionRejectedError{
162				Slot:     slot,
163				Record:   id,
164				Version:  env.State.Rules.Version,
165				Accepted: append([]string(nil), acceptedVersions...),
166			}
167		}
168		return envToRecord(env), nil
169	}
