171	// Record 按标识读取槽的一份历史记录（覆盖、升级或确认恢复之后，较早的
172	// 旧记录仍可按其标识读取）。
173	//
174	// 与 Latest 一样检查记录格式版本、内容校验和（含父记录关系）与规则版本，
175	// 且记录必须属于该槽的历史链：因此槽指针无法解析或顶层 latest/history
176	// 字段重复时，即使所按标识的记录本身完好，也先返回带槽名的 *CorruptError，
177	// 不交付该记录。acceptedVersions 必须显式给出调用方可以接受的规则版本：
178	// 记录完好但版本不在集合内时返回 *VersionRejectedError。
179	// 读取不会切换槽当前记录，不会修补记录，也不会替换记录中的规则版本。
180	func (a *Archive) Record(slot string, id RecordID, acceptedVersions []string) (Record, error) {
181		if !validSlotName(slot) {
182			return Record{}, &NotFoundError{Slot: slot}
183		}
184		lock, err := acquireSharedLock(a.dir)
185		if err != nil {
186			return Record{}, err
187		}
188		defer lock.release()
189	
190		if err := a.assertInSlotHistoryLocked(slot, id); err != nil {
191			return Record{}, err
192		}
193		env, err := a.loadAndVerifyLocked(id)
194		if err != nil {
195			if ce, ok := err.(*CorruptError); ok {
196				ce.Slot = slot
197			}
198			return Record{}, err
199		}
200		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
201			return Record{}, &VersionRejectedError{
202				Slot:     slot,
203				Record:   id,
204				Version:  env.State.Rules.Version,
205				Accepted: append([]string(nil), acceptedVersions...),
206			}
207		}
208		return envToRecord(env), nil
209	}
