211	// History 浏览槽已经保存生效的历史，返回每条记录的元信息（记录标识、
212	// 父标识、槽首标记、规则版本），供先浏览、再用 [Archive.Record] 按标识
213	// 读取完整世界。
214	//
215	// 次序按该槽“保存生效的先后”排列：最近一次成功保存的记录在最前，槽首
216	// 记录在末尾。它既不按记录里的世界时间片排序，也不按记录文件的修改时间
217	// 排序——确认恢复允许时间片回到较早来源的时刻，那次保存产生的新记录仍排
218	// 在最前，而原先已经生效的其他保存按原次序保留。
219	//
220	// 父标识表示“这条记录由哪一次保存承接而来”，与列表次序是两回事。槽首
221	// 标记不能统一解释成“父标识为空”：只有直接建立的槽首记录没有父记录；
222	// 分支槽的首条记录虽然标记为槽首，却以来源槽的那条记录为父记录。分支槽
223	// 只列分支自身保存生效的记录，不会因为分支首记录的父指向来源槽，就把
224	// 来源槽的历史补进列表。
225	//
226	// 列表只做完整性检查，不筛选规则版本：History 没有可接受版本参数，一份
227	// 记录只要确实保存生效且通过与 Record 一致的完整性检查——标识与文件一致、
228	// 文本编码合法、同一对象内名称不重复、记录格式受支持、内容校验和正确
229	// （含父记录关系）、世界状态合法、直接父记录文件存在——即使规则版本较旧或陌生也照常列出。因此“出现在列表里”
230	// 只说明记录完好，不保证调用方立即可用：用 Record 读取时仍必须显式给出
231	// 可接受版本集合，版本不被接受会得到 *VersionRejectedError，不能据此认为
232	// 历史列错了。
233	//
234	// 带历史索引的槽中，单条损坏、缺失或无法解析的记录只被略过，列表继续
235	// 返回其余合格记录，最新或某条中间记录出问题不会让整个浏览失败；但直接
236	// 父记录文件被删除的子记录因不满足父关系要求也被略过，而父文件仍在、
237	// 只是内容损坏时，不因此略过自身完好的子记录。旧版本写出的无历史索引槽
238	// 沿校验通过的父链在内存中重建，只列仍能确认归属本槽的记录，重建在损坏
239	// 处停止，不能承诺越过损坏处继续寻找更老的记录。
240	//
241	// 槽存在但没有任何合格记录时，返回成功的非 nil 空列表；槽不存在返回
242	// *NotFoundError，槽指针无法解析（含顶层 latest/history 字段重复）返回
243	// *CorruptError，三者互不等同，不能把不存在或损坏当成空列表。槽指针
244	// 字段重复时不返回任何历史列表，也不按其中任意一份历史继续浏览。浏览只做
245	// 只读遍历，不切换槽当前记录、不修补或删除记录、不改写历史与世界规则。
246	func (a *Archive) History(slot string) ([]RecordInfo, error) {
247		if !validSlotName(slot) {
248			return nil, &NotFoundError{Slot: slot}
249		}
250		lock, err := acquireSharedLock(a.dir)
251		if err != nil {
252			return nil, err
253		}
254		defer lock.release()
255	
256		history, err := a.slotHistoryLocked(slot)
257		if err != nil {
258			return nil, err
259		}
260		infos := make([]RecordInfo, 0, len(history))
261		for _, id := range history {
262			// 与 Record 相同的完整性检查（不做规则版本取舍）：任何一条
263			// 记录损坏、缺失或无法解析都只略过它本身，不读其中的父标识或
264			// 槽首标记去扩大或缩小遍历范围，也不让整个列表失败。
265			env, verifyErr := a.loadAndVerifyLocked(id)
266			if verifyErr != nil {
267				continue
268			}
269			infos = append(infos, RecordInfo{
270				ID:        env.ID,
271				Parent:    env.Parent,
272				SlotFirst: env.SlotFirst,
273				Version:   env.State.Rules.Version,
274			})
275		}
276		return infos, nil
277	}
278	
279	// RecoverLatest 返回该槽“按保存生效次序最近的一份”内容校验通过且规则
280	// 版本可接受的已保存记录。
281	//
282	// 遍历次序完全来自槽指针维护的历史索引（最新在前），既不依据文件修改
283	// 时间，也不读取受损记录里的父标识或槽首标记：因此最新记录被删除、
284	// 截断成无法解析的内容，或连同若干中间记录一起损坏时，仍能越过它们
285	// 找到本槽更早的可用记录，而不会被引向别的槽或遮住更早的可用记录。遍历
286	// 次序与世界时间片的大小无关；时间片为负的记录属于损坏记录，同样被越过。
287	// 格式版本不受支持的记录（即使校验和匹配、状态合法）同样被越过，连续
288	// 多份未知格式记录也不会遮住其后格式受支持的完好记录。
289	//
290	// 分支槽只在分支自身已成功保存的记录中查找；即使分支首条记录损坏也不
291	// 越过分支边界，其他槽即使种子和规则相同也不会替代。版本不被接受的
292	// 记录一律跳过且不自动升级。只有记录文件写完且指针已更新（即保存完整
293	// 生效）的记录才在候选中：残留临时文件、写完但尚未完成保存的孤儿记录
294	// 不会被选中。
295	//
296	// 槽不存在返回 *NotFoundError；槽指针不可读（无法解析，或顶层
297	// latest/history 字段重复导致含义有歧义）返回带槽名的 *CorruptError，
298	// 字段重复时不按任意一份历史继续查找旧记录，也不改报不可恢复；槽中没有
299	// 任何版本可接受的完好记录时返回包装了 ErrUnrecoverable 的
300	// *UnrecoverableError，可用 errors.Is(err, ErrUnrecoverable) 判断。
301	// 恢复读取不会改写槽、指针、历史记录或规则，重复读取也不消耗历史。
302	func (a *Archive) RecoverLatest(slot string, acceptedVersions []string) (Record, error) {
303		if !validSlotName(slot) {
304			return Record{}, &NotFoundError{Slot: slot}
305		}
306		lock, err := acquireSharedLock(a.dir)
307		if err != nil {
308			return Record{}, err
309		}
310		defer lock.release()
311	
312		history, err := a.slotHistoryLocked(slot)
313		if err != nil {
314			return Record{}, err
315		}
316	
317		env, err := a.firstRecoverableLocked(history, acceptedVersions)
318		if err != nil {
319			var ue *UnrecoverableError
320			if errors.As(err, &ue) {
321				ue.Slot = slot
322			}
323			return Record{}, err
324		}
325		return envToRecord(env), nil
326	}
327	
328	// firstRecoverableLocked 在调用方已持锁的前提下，按给定的保存生效次序
329	// （最新在前）返回第一份“内容与父关系校验通过且规则版本可接受”的记录。
330	//
331	// 文件缺失、截断、文本编码损坏、同一对象内名称重复、格式版本不受支持、
332	// 校验和不符、记录标识不符、父关系异常、时间片为负或世界状态不自洽的
333	// 记录一律越过（不读其中的父标识或槽首标记）；
334	// 版本不被接受的记录也越过且不自动升级。次序完全由调用方给出（来自槽指针
335	// 历史索引或沿可信父链的重建），因此不会被引向别的槽。没有任何可用记录时
336	// 返回包装了 ErrUnrecoverable 的 *UnrecoverableError（Slot 字段由调用方
337	// 补全）。
338	func (a *Archive) firstRecoverableLocked(history []RecordID, acceptedVersions []string) (*envelope, error) {
339		var lastReason string
340		for _, id := range history {
341			env, verifyErr := a.loadAndVerifyLocked(id)
342			if verifyErr != nil {
343				lastReason = verifyErr.Error()
344				continue
345			}
346			if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
347				lastReason = (&VersionRejectedError{
348					Record:  id,
349					Version: env.State.Rules.Version,
350				}).Error()
351				continue
352			}
353			return env, nil
354		}
355	
356		if lastReason == "" {
357			lastReason = "槽中没有任何可确认归属的历史记录"
358		}
359		return nil, &UnrecoverableError{Reason: lastReason}
360	}
361

