1	package world
2	
3	import (
4		"errors"
5		"fmt"
6	)
7	
8	// ConflictError 表示保存与存档当前状态冲突：槽重名、覆盖所依据的
9	// 记录已不是该槽最新记录等。调用方应当重新读取后再决定是否重试。
10	type ConflictError struct {
