44		Reason string
45	}
46	
47	func (e *CorruptError) Error() string {
48		where := e.Slot
49		if e.Record != "" {
50			if where != "" {
51				where += "/"
52			}
53			where += string(e.Record)
54		}
55		if where == "" {
56			where = "?"
57		}
