1	package world
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"strings"
8		"testing"
9	)
10	
11	// 仅 Unicode 转义还原后与字段标签同名的 JSON 键写法：JSON 解码后分别是
12	// "latest" 与 "history"，但文本形态与直接写法不同。
13	const (
14		escLatestKey  = "\\u006catest"
15		escHistoryKey = "\\u0068istory"
16	)
17	
18	// writePointerRaw 以原始字节直接覆盖槽指针文件，用于手工构造生产写入路径
19	// 不会产生的歧义指针（重复字段、只出现一次的大小写/转义写法等）。
20	func writePointerRaw(t *testing.T, a *Archive, slot, raw string) {
21		t.Helper()
22		if err := os.WriteFile(a.slotPath(slot), []byte(raw), 0o600); err != nil {
23			t.Fatal(err)
24		}
25	}
26	
27	// quotedRecordIDs 把记录标识序列化成 JSON 数组文本（紧凑形式）。
28	func quotedRecordIDs(ids []RecordID) string {
29		parts := make([]string, len(ids))
30		for i, id := range ids {
31			parts[i] = fmt.Sprintf("%q", id)
32		}
33		return "[" + strings.Join(parts, ", ") + "]"
34	}
35	
36	// assertPointerDuplicateCorrupt 断言 err 是带槽名、原因明确说明槽指针字段
37	// 重复的 *CorruptError：不是版本不被接受，不是没有可恢复记录，也不是其他
38	// 错误类型。
39	func assertPointerDuplicateCorrupt(t *testing.T, err error, slot string) {
40		t.Helper()
41		ce, ok := err.(*CorruptError)
42		if !ok {
43			t.Fatalf("应为 *CorruptError，得到 %T: %v", err, err)
44		}
45		if ce.Slot != slot {
46			t.Fatalf("CorruptError 应带槽名 %q，得到 %q", slot, ce.Slot)
47		}
48		if !strings.Contains(ce.Error(), "重复") {
49			t.Fatalf("错误应明确说明槽指针字段重复: %v", ce)
50		}
51		if errors.Is(err, ErrUnrecoverable) {
52			t.Fatalf("槽指针字段重复不应报成没有可恢复记录: %v", err)
53		}
54		if _, ok := err.(*VersionRejectedError); ok {
55			t.Fatalf("槽指针字段重复不应报成版本不被接受: %v", err)
56		}
57	}
58	
59	// TestSlotPointerDuplicateFieldCorrupt 槽指针顶层对象内，只要两个名称会被
60	// 现有读取方式解释为 latest 或 history 中的同一字段，整个指针即损坏：完全
61	// 同名、只改大小写、Unicode 转义还原后同名都算。两个值相同、一个为空、
62	// 后一份历史更完整、所指记录全部完好都不豁免；交换先后顺序结果相同。
63	// Latest、Record、History、RecoverLatest、PreviewRecovery 全部返回带槽名、
64	// 说明字段重复的 *CorruptError，不返回记录、历史列表或恢复来源；读取保持
65	// 只读，不修补指针。
66	func TestSlotPointerDuplicateFieldCorrupt(t *testing.T) {
67		// 不存在的标识：若错误地选用了写它的那一份字段，读取会走到记录缺失
68		// 而不是字段重复。
69		const missing = RecordID("rdeadbeefdeadbeefdeadbeefdeadbeef")
70	
71		cases := []struct {
72			name string
73			raw  func(latest RecordID, full, short []RecordID) string
74		}{
75			// ---- latest 重复 ----
76			{"latest同名异值假前真后", func(id RecordID, full, _ []RecordID) string {
77				return fmt.Sprintf(`{"latest": %q, "latest": %q, "history": %s}`, missing, id, quotedRecordIDs(full))
78			}},
79			{"latest同名异值真前假后", func(id RecordID, full, _ []RecordID) string {
80				return fmt.Sprintf(`{"latest": %q, "latest": %q, "history": %s}`, id, missing, quotedRecordIDs(full))
81			}},
82			{"latest同名同值", func(id RecordID, full, _ []RecordID) string {
83				return fmt.Sprintf(`{"latest": %q, "latest": %q, "history": %s}`, id, id, quotedRecordIDs(full))
84			}},
85			{"latest空值在前", func(id RecordID, full, _ []RecordID) string {
86				return fmt.Sprintf(`{"latest": "", "latest": %q, "history": %s}`, id, quotedRecordIDs(full))
87			}},
88			{"latest空值在后", func(id RecordID, full, _ []RecordID) string {
89				return fmt.Sprintf(`{"latest": %q, "latest": "", "history": %s}`, id, quotedRecordIDs(full))
90			}},
91			{"latest大小写异值大写在前", func(id RecordID, full, short []RecordID) string {
92				return fmt.Sprintf(`{"Latest": %q, "latest": %q, "history": %s}`, id, short[0], quotedRecordIDs(full))
93			}},
94			{"latest大小写异值小写在前", func(id RecordID, full, short []RecordID) string {
95				return fmt.Sprintf(`{"latest": %q, "Latest": %q, "history": %s}`, short[0], id, quotedRecordIDs(full))
96			}},
97			{"latest大小写同值", func(id RecordID, full, _ []RecordID) string {
98				return fmt.Sprintf(`{"Latest": %q, "latest": %q, "history": %s}`, id, id, quotedRecordIDs(full))
99			}},
100			// l 还原为小写 l；转义写法在前，直接写法在后，两值不同。
101			{"latestUnicode转义在前", func(id RecordID, full, short []RecordID) string {
102				return fmt.Sprintf("{\"%s\": %q, \"latest\": %q, \"history\": %s}",
103					escLatestKey, id, short[0], quotedRecordIDs(full))
104			}},
105			{"latestUnicode转义在后", func(id RecordID, full, short []RecordID) string {
106				return fmt.Sprintf("{\"latest\": %q, \"%s\": %q, \"history\": %s}",
107					short[0], escLatestKey, id, quotedRecordIDs(full))
108			}},
109			// ---- history 重复 ----
110			{"history同名短前全后", func(id RecordID, full, short []RecordID) string {
111				return fmt.Sprintf(`{"latest": %q, "history": %s, "history": %s}`, id, quotedRecordIDs(short), quotedRecordIDs(full))
112			}},
113			{"history同名全前短后", func(id RecordID, full, short []RecordID) string {
114				return fmt.Sprintf(`{"latest": %q, "history": %s, "history": %s}`, id, quotedRecordIDs(full), quotedRecordIDs(short))
115			}},
116			{"history同名同一份", func(id RecordID, full, _ []RecordID) string {
117				return fmt.Sprintf(`{"latest": %q, "history": %s, "history": %s}`, id, quotedRecordIDs(full), quotedRecordIDs(full))
118			}},
119			{"history空数组在前", func(id RecordID, full, _ []RecordID) string {
120				return fmt.Sprintf(`{"latest": %q, "history": [], "history": %s}`, id, quotedRecordIDs(full))
121			}},
122			{"history空数组在后", func(id RecordID, full, _ []RecordID) string {
123				return fmt.Sprintf(`{"latest": %q, "history": %s, "history": []}`, id, quotedRecordIDs(full))
124			}},
125			{"history大小写短前全后", func(id RecordID, full, short []RecordID) string {
126				return fmt.Sprintf(`{"latest": %q, "History": %s, "history": %s}`, id, quotedRecordIDs(short), quotedRecordIDs(full))
127			}},
128			{"history大小写全前短后", func(id RecordID, full, short []RecordID) string {
129				return fmt.Sprintf(`{"latest": %q, "history": %s, "History": %s}`, id, quotedRecordIDs(full), quotedRecordIDs(short))
130			}},
131			// h 还原为小写 h；转义形式给出短历史，直接写法给出完整历史。
132			{"historyUnicode转义短前全后", func(id RecordID, full, short []RecordID) string {
133				return fmt.Sprintf("{\"latest\": %q, \"%s\": %s, \"history\": %s}",
134					id, escHistoryKey, quotedRecordIDs(short), quotedRecordIDs(full))
135			}},
136			{"historyUnicode转义全前短后", func(id RecordID, full, short []RecordID) string {
137				return fmt.Sprintf("{\"latest\": %q, \"history\": %s, \"%s\": %s}",
138					id, quotedRecordIDs(full), escHistoryKey, quotedRecordIDs(short))
139			}},
140			// 重复字段的值类型不对会令 json.Unmarshal 失败，但歧义仍要明确报
141			// 字段重复，而不是笼统的“无法解析”。
142			{"latest重复其一值类型错误", func(id RecordID, full, _ []RecordID) string {
143				return fmt.Sprintf(`{"latest": ["x"], "latest": %q, "history": %s}`, id, quotedRecordIDs(full))
144			}},
145			{"history重复其一值类型错误", func(id RecordID, full, _ []RecordID) string {
146				return fmt.Sprintf(`{"latest": %q, "history": "x", "history": %s}`, id, quotedRecordIDs(full))
147			}},
148		}
149	
150		for _, tc := range cases {
151			t.Run(tc.name, func(t *testing.T) {
152				a, _ := newTestArchive(t)
153				ids := saveN(t, a, "s", 2) // r2 r1 r0，全部完好
154				raw := tc.raw(ids[0], ids, ids[:2])
155				writePointerRaw(t, a, "s", raw)
156	
157				_, err := a.Latest("s", []string{"v1"})
158				assertPointerDuplicateCorrupt(t, err, "s")
159	
160				// 版本不被接受也不能掩盖指针损坏：先报损坏而非版本拒绝。
161				_, err = a.Latest("s", []string{"other"})
162				assertPointerDuplicateCorrupt(t, err, "s")
163	
164				// 即使按标识读取的是一份完好历史记录，也必须先确认它在槽历史中，
165				// 因而同样拒绝。
166				_, err = a.Record("s", ids[0], []string{"v1"})
167				assertPointerDuplicateCorrupt(t, err, "s")
168				_, err = a.Record("s", ids[1], []string{"v1"})
169				assertPointerDuplicateCorrupt(t, err, "s")
170	
171				if _, err := a.History("s"); err == nil {
172					t.Fatal("历史浏览应返回字段重复的 *CorruptError，而不是历史列表")
173				} else {
174					assertPointerDuplicateCorrupt(t, err, "s")
175				}
176	
177				if _, err := a.RecoverLatest("s", []string{"v1"}); err == nil {
178					t.Fatal("恢复读取必须拒绝，不能按任意一份 history 继续查找旧记录")
179				} else {
180					assertPointerDuplicateCorrupt(t, err, "s")
181				}
182	
183				if _, err := a.PreviewRecovery("s", []string{"v1"}); err == nil {
184					t.Fatal("恢复预览必须拒绝，不能返回恢复来源")
185				} else {
186					assertPointerDuplicateCorrupt(t, err, "s")
187				}
188	
189				// 只读：指针字节原样保留，不自动修补或删去重复字段。
190				if got, err := os.ReadFile(a.slotPath("s")); err != nil || string(got) != raw {
191					t.Fatalf("读取改写了含重复字段的槽指针: %q err=%v", string(got), err)
192				}
193			})
194		}
195	}
196	
197	// TestSlotPointerDuplicateRejectsWrites 需要依赖槽指针承接当前记录与历史的
198	// 写入操作，遇到重复字段指针时一律拒绝：不创建新记录，不自动修补字段，
199	// 指针与已有记录原样保留。
200	func TestSlotPointerDuplicateRejectsWrites(t *testing.T) {
201		a, dir := newTestArchive(t)
202		ids := saveN(t, a, "s", 2)
203	
204		// 在损坏指针前先取回一个可用世界与元信息。
205		rec, err := a.Record("s", ids[0], []string{"v1"})
206		if err != nil {
207			t.Fatal(err)
208		}
209		w, err := WorldFromState(rec.State)
210		if err != nil {
211			t.Fatal(err)
212		}
213		good := saveBase(t, a, "good")
214	
215		raw := fmt.Sprintf(`{"latest": %q, "latest": %q, "history": %s}`,
216			ids[0], ids[1], quotedRecordIDs(ids))
217		writePointerRaw(t, a, "s", raw)
218		before := recordCount(t, a)
219	
220		reject := func(name string, fn func() error) {
221			t.Helper()
222			t.Run(name, func(t *testing.T) {
223				err := fn()
224				assertPointerDuplicateCorrupt(t, err, "s")
225				if got := recordCount(t, a); got != before {
226					t.Fatalf("被拒绝的 %s 不应产生新记录: %d -> %d", name, before, got)
227				}
228				if got, rerr := os.ReadFile(a.slotPath("s")); rerr != nil || string(got) != raw {
229					t.Fatalf("%s 改写了含重复字段的槽指针", name)
230				}
231			})
232		}
233	
234		reject("Save", func() error {
235			_, err := a.Save("s", w)
236			return err
237		})
238		reject("Replace", func() error {
239			_, err := a.Replace("s", w, ids[0])
240			return err
241		})
242		reject("CheckUpgrade", func() error {
243			_, err := a.CheckUpgrade("s", []string{"v1"}, v2Rules())
244			return err
245		})
246		reject("Upgrade", func() error {
247			_, err := a.Upgrade("s", []string{"v1"}, v2Rules(), ids[0])
248			return err
249		})
250		reject("PreviewMigration", func() error {
251			_, err := a.PreviewMigration("s", []string{"v1"}, v2Rules(), nil, nil)
252			return err
253		})
254		reject("Migrate", func() error {
255			_, err := a.Migrate("s", []string{"v1"}, v2Rules(), nil, nil, ids[0])
256			return err
257		})
258		reject("ConfirmRecovery", func() error {
259			_, err := a.ConfirmRecovery("s", ids[0], ids[1], []string{"v1"})
260			return err
261		})
262		reject("Branch源槽", func() error {
263			_, err := a.Branch("s", ids[1], "b")
264			return err
265		})
266	
267		// 从正常槽分支到一个指针已损坏的已存在槽：目标槽读取报字段重复，
268		// 不能把它当成可创建的空槽。
269		t.Run("Branch目标槽", func(t *testing.T) {
270			_, err := a.Branch("good", good.ID, "s")
271			assertPointerDuplicateCorrupt(t, err, "s")
272			if got := recordCount(t, a); got != before {
273				t.Fatalf("被拒绝的 Branch 不应产生新记录: %d -> %d", before, got)
274			}
275			if _, err := a.readLatestLocked("good"); err != nil {
276				t.Fatalf("源正常槽不应受影响: %v", err)
277			}
278		})
279	
280		// 重新打开目录本身不受影响；坏槽依旧损坏，正常槽继续可用。
281		a2, err := Open(dir)
282		if err != nil {
283			t.Fatalf("含坏槽的存档目录应能打开: %v", err)
284		}
285		if _, err := a2.Latest("s", []string{"v1"}); err == nil {
286			t.Fatal("重开后坏槽仍应损坏")
287		} else {
288			assertPointerDuplicateCorrupt(t, err, "s")
289		}
290		if g, err := a2.Latest("good", []string{"v1"}); err != nil || g.ID != good.ID {
291			t.Fatalf("其他正常槽应继续可读: id=%s err=%v", g.ID, err)
292		}
293	}
294	
295	// TestRecoverDuplicateHistoryNoFallback history 字段重复、两份历史内容不同
296	// 时，恢复读取与预览不能挑其中一份继续：即使其中一份完整指向全部完好记录、
297	// 交换两份次序也都得到相同的字段重复损坏结果。
298	func TestRecoverDuplicateHistoryNoFallback(t *testing.T) {
299		a, _ := newTestArchive(t)
300		ids := saveN(t, a, "s", 2)
301		onlyMissing := []RecordID{RecordID("r00000000000000000000000000000000")}
302	
303		for _, swapped := range []bool{false, true} {
304			var raw string
305			if !swapped {
306				raw = fmt.Sprintf(`{"latest": %q, "history": %s, "history": %s}`,
307					ids[0], quotedRecordIDs(onlyMissing), quotedRecordIDs(ids))
308			} else {
309				raw = fmt.Sprintf(`{"latest": %q, "history": %s, "history": %s}`,
310					ids[0], quotedRecordIDs(ids), quotedRecordIDs(onlyMissing))
311			}
312			writePointerRaw(t, a, "s", raw)
313	
314			if _, err := a.RecoverLatest("s", []string{"v1"}); err == nil {
315				t.Fatalf("swapped=%v: 不能按完整的那份 history 恢复出完好记录", swapped)
316			} else {
317				assertPointerDuplicateCorrupt(t, err, "s")
318			}
319			if pv, err := a.PreviewRecovery("s", []string{"v1"}); err == nil {
320				t.Fatalf("swapped=%v: 预览不能返回 current=%s source=%s", swapped, pv.Current, pv.Source)
321			} else {
322				assertPointerDuplicateCorrupt(t, err, "s")
323			}
324		}
325	}
326	
327	// TestSlotPointerSingleVariantAndLegacyReadable 字段名称只出现一次时，既有
328	// 可接受的大小写与 Unicode 转义写法继续可读；旧版本仅含 latest 的裸指针
329	// 继续可用，缺少 history 不算重复。
330	func TestSlotPointerSingleVariantAndLegacyReadable(t *testing.T) {
331		a, dir := newTestArchive(t)
332		ids := saveN(t, a, "s", 2)
333		v1 := []string{"v1"}
334	
335		variants := []string{
336			// 两个字段都改成首字母大写写法，各出现一次。
337			fmt.Sprintf(`{"Latest": %q, "History": %s}`, ids[0], quotedRecordIDs(ids)),
338			// latest 以 Unicode 转义书写（l -> l），只出现一次。
339			fmt.Sprintf("{\"%s\": %q, \"history\": %s}", escLatestKey, ids[0], quotedRecordIDs(ids)),
340			// history 以 Unicode 转义书写（h -> h），只出现一次。
341			fmt.Sprintf("{\"latest\": %q, \"%s\": %s}", ids[0], escHistoryKey, quotedRecordIDs(ids)),
342			// 旧版本裸指针：没有 history 字段，沿校验通过的父链重建历史。
343			fmt.Sprintf(`{"latest": %q}`, ids[0]),
344			// 不映射到任何固定字段的多余键即使彼此仅大小写不同，也不被解释为
345			// latest/history，继续按原方式忽略。
346			fmt.Sprintf(`{"latest": %q, "history": %s, "extra": 1, "Extra": 2}`,
347				ids[0], quotedRecordIDs(ids)),
348		}
349		for i, raw := range variants {
350			writePointerRaw(t, a, "s", raw)
351	
352			rec, err := a.Latest("s", v1)
353			if err != nil {
354				t.Fatalf("变体 %d 只出现一次的可接受写法应继续可读: %v\n%s", i, err, raw)
355			}
356			if rec.ID != ids[0] {
357				t.Fatalf("变体 %d 当前标识错误: %s", i, rec.ID)
358			}
359			infos, err := a.History("s")
360			if err != nil {
361				t.Fatalf("变体 %d 历史应可读（裸指针可重建）: %v", i, err)
362			}
363			if len(infos) != len(ids) || infos[0].ID != ids[0] || infos[len(ids)-1].ID != ids[2] {
364				t.Fatalf("变体 %d 历史次序错误: %+v", i, infos)
365			}
366		}
367	
368		// 重开后旧裸指针仍只读可用。
369		writePointerRaw(t, a, "s", fmt.Sprintf(`{"latest": %q}`, ids[0]))
370		a2, err := Open(dir)
371		if err != nil {
372			t.Fatal(err)
373		}
374		if rec, err := a2.RecoverLatest("s", v1); err != nil || rec.ID != ids[0] {
375			t.Fatalf("旧裸指针恢复读取应继续可用: %+v err=%v", rec, err)
376		}
377	}
378	
379	// TestSlotPointerDuplicateRecordIDInHistoryUnchanged history 数组里同一记录
380	// 标识出现多次，与字段名称写两次是不同情况：浏览继续按首次出现次序去重，
381	// Latest、Record 与恢复读取照常工作，不能误报字段重复。
382	func TestSlotPointerDuplicateRecordIDInHistoryUnchanged(t *testing.T) {
383		a, _ := newTestArchive(t)
384		ids := saveN(t, a, "s", 2)
385		withDup := append([]RecordID{ids[0]}, ids...) // r2, r2, r1, r0
386		writePointerRaw(t, a, "s",
387			fmt.Sprintf(`{"latest": %q, "history": %s}`, ids[0], quotedRecordIDs(withDup)))
388	
389		if _, err := a.Latest("s", []string{"v1"}); err != nil {
390			t.Fatalf("history 数组内标识重复不是字段重复，Latest 应可读: %v", err)
391		}
392		infos, err := a.History("s")
393		if err != nil {
394			t.Fatalf("history 数组内标识重复不应让浏览失败: %v", err)
395		}
396		if len(infos) != len(ids) {
397			t.Fatalf("应按首次出现次序去重: %+v", infos)
398		}
399		for i, want := range ids {
400			if infos[i].ID != want {
401				t.Fatalf("去重后次序应保持不变: %+v", infos)
402			}
403		}
404		if _, err := a.Record("s", ids[1], []string{"v1"}); err != nil {
405			t.Fatalf("历史记录应可读: %v", err)
406		}
407		if rec, err := a.RecoverLatest("s", []string{"v1"}); err != nil || rec.ID != ids[0] {
408			t.Fatalf("恢复读取应正常: rec=%+v err=%v", rec, err)
409		}
410	}
411	
412	// TestSlotPointerCorruptDoesNotAffectOtherSlots 一个槽的指针字段重复不影响
413	// 打开存档目录、列出槽位或使用其他正常槽；损坏槽也不会被 Slots 悄悄隐藏。
414	func TestSlotPointerCorruptDoesNotAffectOtherSlots(t *testing.T) {
415		a, dir := newTestArchive(t)
416		bad := saveBase(t, a, "bad")
417		good := saveBase(t, a, "good")
418		writePointerRaw(t, a, "bad",
419			fmt.Sprintf(`{"latest": %q, "latest": %q}`, bad.ID, good.ID))
420	
421		a2, err := Open(dir)
422		if err != nil {
423			t.Fatalf("存档目录应能打开: %v", err)
424		}
425		names, err := a2.Slots()
426		if err != nil {
427			t.Fatal(err)
428		}
429		seen := map[string]bool{}
430		for _, n := range names {
431			seen[n] = true
432		}
433		if !seen["bad"] || !seen["good"] {
434			t.Fatalf("两个槽都应仍被列出: %v", names)
435		}
436		if _, err := a2.Latest("good", []string{"v1"}); err != nil {
437			t.Fatalf("正常槽应继续可读: %v", err)
438		}
439		if _, err := a2.History("good"); err != nil {
440			t.Fatalf("正常槽历史应继续可浏览: %v", err)
441		}
442		if _, err := a2.Latest("bad", []string{"v1"}); err == nil {
443			t.Fatal("坏槽应继续报损坏")
444		} else {
445			assertPointerDuplicateCorrupt(t, err, "bad")
446		}
447	}
