package world

import (
	"bytes"
	"encoding/json"
	"fmt"
	"reflect"
	"strings"
)

// 记录读入时的重复名称检查直接建立在真实记录结构之上：检查所认识的固定
// 字段、字段名称（含 json 标签）与嵌套关系全部由 envelope 及其引用到的
// 结构体经反射派生，不再手工登记第二份字段清单。结构体增删或改名字段、
// 调整 json 标签或嵌套后，重复检查随之自动一致，无需再同步维护另一张表。
//
// 派生规则与 encoding/json 的解码目标一一对应：
//   - 结构体对象的每个可导出且未标记 "-" 的字段是一个固定字段，字段名取
//     json 标签名（无标签时取 Go 字段名）；encoding/json 对固定字段做大小
//     写不敏感匹配，所以重复判定也按归并后的字段名折叠大小写与 Unicode
//     转义写法（"Time" 与 "time" 是同一个固定字段）。
//   - 解码到 map 的对象（携带上限 map[string]int）没有固定字段，其键是真实
//     业务标识（角色名），按 Unicode 转义还原后的精确名称比较：hero 与
//     HERO 是两个角色，必须分别保留；同一精确键写两次才算重复。
//   - 不属于记录结构的多余对象（被忽略的未知字段值）同样没有固定字段，
//     其中的键按还原后的精确名称判定：精确重复拒绝，不把未知名称一律当成
//     固定字段做大小写折叠。
//
// 固定字段的 Go 类型决定嵌套：结构体/结构体指针是对象子节点，数组/切片是
// 数组子节点（元素是结构体时其元素对象登记为对应结构体），其余为标量。
// 这与 encoding/json 实际会进入的容器完全相同，包括 map[string]int 这个
// 唯一解码到 map 的字段。

// recordRoot 是重复名称检查遍历的根类型，即记录文件在磁盘上的完整结构。
// 记录结构发生变化时，检查经由这里自动跟随，无需另行登记字段。
var recordRoot = reflect.TypeOf(envelope{})

// recordObject 描述检查遍历时一类 JSON 对象的结构，全部由真实 Go 类型派生。
type recordObject struct {
	// fixed 为 true 时该对象解码到结构体：fields 列出它的固定字段，重复
	// 判定按字段名大小写不敏感归并。为 false 时对象解码到 map 或属于被
	// 忽略的多余对象：没有固定字段，键按还原后的精确名称判定。
	fixed bool
	// fields 按 Go 字段索引保存固定字段的 JSON 名称与值容器信息。
	fields []recordField
	// byFold 把会折叠到同一固定字段的名称（小写形式）映射到 fields 下标。
	byFold map[string]int
}

// recordField 是一个固定字段的 JSON 名称与其值对应的 JSON 容器类型。
type recordField struct {
	name string
	ch   byte // 0 表示标量；'{' 表示对象，'[' 表示数组
	// obj 为 ch=='{' 时给出值对象的结构描述下标；elem 为 ch=='[' 且数组
	// 元素是结构体时给出元素对象的结构描述下标。
	obj  int
	elem int
}

// recordObjects 是按真实类型构建出的对象结构描述表：根信封位于下标 0，
// 其余下标为遍历中遇到的结构体类型；-1 表示“没有登记的对象类型”（数组
// 元素是标量、或多余对象）。
var recordObjects = buildRecordObjects(recordRoot)

// unknownObject 是不属于记录结构的多余对象使用的描述：无固定字段、键按
// 还原后的精确名称判定。它始终是表中的最后一项。
const unknownObject = -1

func buildRecordObjects(root reflect.Type) []recordObject {
	// 结构体类型 -> 描述下标。map 与多余对象不进此表：map 字段直接引用
	// 动态构建的 map 描述，多余对象统一用 unknownObject。
	index := map[reflect.Type]int{}
	var objs []recordObject

	mapDesc := map[reflect.Type]int{}
	ensureMap := func(t reflect.Type) int {
		if i, ok := mapDesc[t]; ok {
			return i
		}
		i := len(objs)
		mapDesc[t] = i
		objs = append(objs, recordObject{fixed: false, byFold: map[string]int{}})
		return i
	}

	var ensureStruct func(t reflect.Type) int
	ensureStruct = func(t reflect.Type) int {
		if i, ok := index[t]; ok {
			return i
		}
		i := len(objs)
		index[t] = i
		// 先占位，使自引用/互相引用的结构体字段在递归中能找到本表。
		objs = append(objs, recordObject{})

		obj := recordObject{fixed: true, byFold: map[string]int{}}
		for fi, n := 0, t.NumField(); fi < n; fi++ {
			sf := t.Field(fi)
			if sf.PkgPath != "" || sf.Tag.Get("json") == "-" {
				continue // 非导出字段或显式不参与 JSON 的字段
			}
			f := recordField{name: jsonFieldName(sf), obj: -1, elem: -1}
			switch ft := sf.Type; ft.Kind() {
			case reflect.Struct:
				f.ch = '{'
				f.obj = ensureStruct(ft)
			case reflect.Ptr:
				if ft.Elem().Kind() == reflect.Struct {
					f.ch = '{'
					f.obj = ensureStruct(ft.Elem())
				}
			case reflect.Map:
				// 记录结构中唯一的 map 字段是携带上限 map[string]int；
				// 其键是真实角色标识，不按固定字段折叠。
				f.ch = '{'
				f.obj = ensureMap(ft)
			case reflect.Slice, reflect.Array:
				f.ch = '['
				if et := ft.Elem(); et.Kind() == reflect.Struct {
					f.elem = ensureStruct(et)
				} else if et.Kind() == reflect.Ptr && et.Elem().Kind() == reflect.Struct {
					f.elem = ensureStruct(et.Elem())
				}
			}
			pos := len(obj.fields)
			obj.fields = append(obj.fields, f)
			// 与 encoding/json 一致：固定字段按小写形式做大小写不敏感
			// 归并。同名字段冲突时 encoding/json 按字段深度/顺序取一个，
			// 记录结构本身不存在这种冲突；首个登记即该字段身份。
			if _, ok := obj.byFold[strings.ToLower(f.name)]; !ok {
				obj.byFold[strings.ToLower(f.name)] = pos
			}
		}
		objs[i] = obj
		return i
	}

	ensureStruct(root)
	return objs
}

// jsonFieldName 返回字段在 JSON 中的名称：优先取 json 标签的名称段，
// 无标签时取 Go 字段名；omitempty 等选项不影响名称。
func jsonFieldName(sf reflect.StructField) string {
	tag := sf.Tag.Get("json")
	if tag == "" {
		return sf.Name
	}
	if comma := strings.IndexByte(tag, ','); comma >= 0 {
		tag = tag[:comma]
	}
	if tag == "" {
		return sf.Name
	}
	return tag
}

// fieldIndex 返回对象 objIdx 中 JSON 键 key 会被 encoding/json 读取到的
// 固定字段下标；key 不对应任何固定字段时返回 false。匹配与
// encoding/json 一致，按小写形式大小写不敏感比较，key 已经是 Unicode
// 转义还原后的字符串。
func fieldIndex(objIdx int, key string) (int, bool) {
	if objIdx < 0 || objIdx >= len(recordObjects) {
		return 0, false
	}
	i, ok := recordObjects[objIdx].byFold[strings.ToLower(key)]
	return i, ok
}

// checkDuplicateNames 检查 JSON 文本中同一对象内的名称是否重复出现。
//
// 名称按 JSON 转义还原后的字符串比较：直接写出的名称与表示同一名称的
// Unicode 转义（如 "ID" 与写作转义形式的同一名称）视为同一名称，不能
// 借此绕过限制。
//
