	"encoding/json"
	"fmt"
	"reflect"
	"strings"
)

// 记录读入时的重复名称检查直接建立在真实记录结构之上：检查所认识的固定
// 字段、字段名称（含 json 标签）与嵌套关系全部由 envelope 及其引用到的
