// jsonFieldName 返回字段在 JSON 中的名称：优先取 json 标签的名称段，
// 无标签时取 Go 字段名；omitempty 等选项不影响名称。
func jsonFieldName(sf reflect.StructField) string {
	tag := sf.Tag.Get("json")
	if tag == "" {
		return sf.Name
	}
	if comma := strings.IndexByte(tag, ','); comma >= 0 {
