			isObj:     true,
			obj:       obj,
			seen:      make(map[string]bool),
			expectKey: true,
		})
	}
	// 一个值（标量或容器）结束后，父对象等待下一个键。
	markValueDone := func() {
		if n := len(stack); n > 0 && stack[n-1].isObj {
			stack[n-1].expectKey = true
		}
	}
