		"ID":        {},
		"Parent":    {},
		"SlotFirst": {},
		"Checksum":  {},
		"State":     {ch: '{', child: objState},
	},
	objState: {
		"Seed":       {},
		"Rules":      {ch: '{', child: objRules},
		"Time":       {},
		"Characters": {ch: '[', elem: objCharacter},
