				dupAfter := wrapAtPath(target, buildRawObject(target, field), segs)
				if err := checkDuplicateNames([]byte(dupAfter)); err == nil ||
					!strings.Contains(err.Error(), "重复") {
					t.Fatalf("固定字段 %q 的大小写折叠重复键（在后）应判损坏，得到 %v:\n%s",
